    47→const PAGE_SIZE = 10;
    48→
    49→export const loader = async ({ request }: LoaderFunctionArgs) => {
    50→  const { session } = await authenticate.admin(request);
    51→  const shop = session.shop;
    52→
    53→  const [zipCodes, subscription] = await Promise.all([
    54→    db.zipCode.findMany({
    55→      where: { shop },
    56→      orderBy: { createdAt: "desc" },
    57→    }),
    58→    getShopSubscription(shop),
    59→  ]);
    60→
    61→  const stats = {
    62→    total: zipCodes.length,
    63→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    64→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    65→    active: zipCodes.filter((z) => z.isActive).length,
    66→  };
    67→
    68→  return { zipCodes, stats, subscription };
    69→};
    70→
    71→export const action = async ({ request }: ActionFunctionArgs) => {
    72→  const { session } = await authenticate.admin(request);
    73→  const shop = session.shop;
    74→  const formData = await request.formData();
    75→  const intent = formData.get("intent");
    76→
    77→  if (intent === "add") {
    78→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
    79→    const label = String(formData.get("label") || "").trim();
    80→    const zone = String(formData.get("zone") || "").trim();
    81→    const message = String(formData.get("message") || "").trim();
    82→    const eta = String(formData.get("eta") || "").trim();
    83→    const type = String(formData.get("type") || "allowed");
    84→
    85→    if (!zipCode) return { error: "Zip code is required." };
    86→
    87→    const subscription = await getShopSubscription(shop);
    88→    const limits = PLAN_LIMITS[subscription.planTier];
    89→
    90→    if (type === "blocked" && !limits.allowBlocked) {
    91→      return {
    92→        error:
    93→          "Blocked zip codes are not available on the Free plan. Upgrade to Pro or Ultimate.",
    94→        upgradeRequired: true,
    95→      };
    96→    }
    97→
    98→    const currentCount = await db.zipCode.count({ where: { shop } });
    99→    if (limits.maxZipCodes !== Infinity && currentCount >= limits.maxZipCodes) {
   100→      return {
   101→        error: `You have reached the ${limits.maxZipCodes} zip code limit for the Free plan. Upgrade to Pro for unlimited zip codes.`,
   102→        upgradeRequired: true,
   103→      };
   104→    }
   105→
   106→    try {
   107→      await db.zipCode.create({
   108→        data: {
   109→          shop,
   110→          zipCode,
   111→          label: label || null,
   112→          zone: zone || null,
   113→          message: message || null,
   114→          eta: eta || null,
   115→          type,
   116→        },
   117→      });
   118→      return { success: true, action: "added", zipCode };
   119→    } catch {
   120→      return { error: `Zip code "${zipCode}" already exists.` };
   121→    }
   122→  }
   123→
   124→  if (intent === "delete") {
   125→    const id = String(formData.get("id"));
   126→    try {
   127→      await db.zipCode.delete({ where: { id } });
   128→      return { success: true, action: "deleted" };
   129→    } catch {
   130→      return { error: "Failed to delete zip code." };
   131→    }
   132→  }
   133→
   134→  if (intent === "update") {
   135→    const id = String(formData.get("id"));
   136→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
   137→    const label = String(formData.get("label") || "").trim();
   138→    const zone = String(formData.get("zone") || "").trim();
   139→    const message = String(formData.get("message") || "").trim();
   140→    const eta = String(formData.get("eta") || "").trim();
   141→    const type = String(formData.get("type") || "allowed");
   142→    const isActive = formData.get("isActive") === "true";
   143→
   144→    if (!zipCode) return { error: "Zip code is required." };
   145→
   146→    try {
   147→      await db.zipCode.update({
   148→        where: { id },
   149→        data: {
   150→          zipCode,
   151→          label: label || null,
   152→          zone: zone || null,
   153→          message: message || null,
   154→          eta: eta || null,
   155→          type,
   156→          isActive,
   157→        },
   158→      });
   159→      return { success: true, action: "updated", zipCode };
   160→    } catch {
   161→      return { error: `Failed to update zip code "${zipCode}". It may already exist.` };
   162→    }
   163→  }
   164→
   165→  if (intent === "toggle") {
   166→    const id = String(formData.get("id"));
   167→    const isActive = formData.get("isActive") === "true";
   168→    try {
   169→      await db.zipCode.update({
   170→        where: { id },
   171→        data: { isActive: !isActive },
   172→      });
   173→      return { success: true, action: "toggled" };
   174→    } catch {
   175→      return { error: "Failed to toggle zip code status." };
   176→    }
   177→  }
   178→
   179→  if (intent === "check") {
   180→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
   181→    try {
   182→      const found = await db.zipCode.findUnique({
   183→        where: { shop_zipCode: { shop, zipCode } },
   184→      });
   185→      if (!found) return { checkResult: { found: false, zipCode } };
   186→      return { checkResult: { found: true, zipCode, record: found } };
   187→    } catch {
   188→      return { error: "Failed to check zip code." };
   189→    }
   190→  }
   191→
   192→  if (intent === "bulk-import") {
   193→    const csvData = String(formData.get("csvData") || "");
   194→    if (!csvData.trim()) return { error: "No CSV data provided." };
   195→
   196→    const subscription = await getShopSubscription(shop);
   197→    const limits = PLAN_LIMITS[subscription.planTier];
   198→
   199→    const lines = csvData
   200→      .split("\n")
   201→      .map((l) => l.trim())
   202→      .filter((l) => l.length > 0);
   203→
   204→    // Skip header row if present
   205→    const startIdx =
   206→      lines.length > 0 &&
   207→      lines[0].toLowerCase().includes("zip")
   208→        ? 1
   209→        : 0;
   210→
   211→    const currentCount = await db.zipCode.count({ where: { shop } });
   212→    let imported = 0;
   213→    let skipped = 0;
   214→    const errors: string[] = [];
   215→
   216→    for (let i = startIdx; i < lines.length; i++) {
   217→      const cols = lines[i].split(",").map((c) => c.trim().replace(/^"|"$/g, ""));
   218→      const zipCode = (cols[0] || "").toUpperCase();
   219→      if (!zipCode) continue;
   220→
   221→      const zone = cols[1] || null;
   222→      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
   223→      const message = cols[3] || null;
   224→      const eta = cols[4] || null;
   225→
   226→      if (type === "blocked" && !limits.allowBlocked) {
   227→        skipped++;
   228→        continue;
   229→      }
   230→
   231→      if (
   232→        limits.maxZipCodes !== Infinity &&
   233→        currentCount + imported >= limits.maxZipCodes
   234→      ) {
   235→        errors.push(
   236→          `Reached the ${limits.maxZipCodes} zip code limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
   237→        );
   238→        break;
   239→      }
   240→
   241→      try {
   242→        await db.zipCode.upsert({
   243→          where: { shop_zipCode: { shop, zipCode } },
   244→          create: {
   245→            shop,
   246→            zipCode,
   247→            zone,
   248→            type,
   249→            message,
   250→            eta,
   251→          },
   252→          update: {
   253→            zone: zone ?? undefined,
   254→            type,
   255→            message: message ?? undefined,
   256→            eta: eta ?? undefined,
   257→          },
   258→        });
   259→        imported++;
   260→      } catch {
   261→        skipped++;
   262→      }
   263→    }
   264→
   265→    return {
   266→      success: true,
   267→      action: "bulk-import",
   268→      imported,
   269→      skipped,
   270→      errors,
   271→    };
   272→  }
   273→
   274→  if (intent === "export") {
   275→    try {
   276→      const zipCodes = await db.zipCode.findMany({
   277→        where: { shop },
   278→        orderBy: { createdAt: "desc" },
   279→      });
   280→
   281→      const header = "Zip Code,Zone,Status,Message,ETA,Active";
   282→      const rows = zipCodes.map(
   283→        (z) =>
   284→          `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}"`,
   285→      );
   286→      const csv = [header, ...rows].join("\n");
   287→
   288→      return { success: true, action: "export", csv };
   289→    } catch {
   290→      return { error: "Failed to export zip codes." };
   291→    }
   292→  }
   293→
   294→  return null;
   295→};
   296→
   297→type ZipCodeRecord = {
   298→  id: string;
   299→  zipCode: string;
   300→  label: string | null;
   301→  zone: string | null;
   302→  message: string | null;
   303→  eta: string | null;
   304→  type: string;
   305→  isActive: boolean;
   306→  createdAt: string | Date;
   307→};
   308→
   309→export default function ZipCodeCheckerPage() {
   310→  const { zipCodes, stats, subscription } = useLoaderData<typeof loader>();
   311→  const fetcher = useFetcher<typeof action>();
   312→  const shopify = useAppBridge();
   313→  const navigate = useNavigate();
   314→
   315→  const limits = PLAN_LIMITS[subscription.planTier];
   316→  const isFreePlan = subscription.planTier === "free";
   317→  const atZipLimit =
   318→    limits.maxZipCodes !== Infinity && stats.total >= limits.maxZipCodes;
   319→
   320→  // Search & filter state
   321→  const [searchQuery, setSearchQuery] = useState("");
   322→  const [statusFilter, setStatusFilter] = useState("all");
   323→  const [currentPage, setCurrentPage] = useState(1);
   324→
   325→  // Check zip code state
   326→  const [checkZip, setCheckZip] = useState("");
   327→
   328→  // Add modal state
   329→  const [addModalOpen, setAddModalOpen] = useState(false);
   330→  const [newZip, setNewZip] = useState("");
   331→  const [newLabel, setNewLabel] = useState("");
   332→  const [newZone, setNewZone] = useState("");
   333→  const [newMessage, setNewMessage] = useState("");
   334→  const [newEta, setNewEta] = useState("");
   335→  const [newType, setNewType] = useState("allowed");
   336→
   337→  // Edit modal state
   338→  const [editModalOpen, setEditModalOpen] = useState(false);
   339→  const [editId, setEditId] = useState("");
   340→  const [editZip, setEditZip] = useState("");
   341→  const [editLabel, setEditLabel] = useState("");
   342→  const [editZone, setEditZone] = useState("");
   343→  const [editMessage, setEditMessage] = useState("");
   344→  const [editEta, setEditEta] = useState("");
   345→  const [editType, setEditType] = useState("allowed");
   346→  const [editIsActive, setEditIsActive] = useState(true);
   347→
   348→  // Import modal state
   349→  const [importModalOpen, setImportModalOpen] = useState(false);
   350→  const [csvText, setCsvText] = useState("");
   351→  const [importFile, setImportFile] = useState<File | null>(null);
   352→
   353→  const isCheckLoading =
   354→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "check";
   355→  const isAddLoading =
   356→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "add";
   357→  const isEditLoading =
   358→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "update";
   359→  const isImportLoading =
   360→    fetcher.state !== "idle" &&
   361→    fetcher.formData?.get("intent") === "bulk-import";
   362→
   363→  const checkResult =
   364→    fetcher.data && "checkResult" in fetcher.data
   365→      ? fetcher.data.checkResult
   366→      : null;
   367→  const actionError =
   368→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   369→  const upgradeRequired =
   370→    fetcher.data && "upgradeRequired" in fetcher.data
   371→      ? fetcher.data.upgradeRequired
   372→      : false;
   373→  const importResult =
   374→    fetcher.data &&
   375→    "action" in fetcher.data &&
   376→    fetcher.data.action === "bulk-import"
   377→      ? fetcher.data
   378→      : null;
   379→
   380→  // Filtered zip codes
   381→  const filteredZipCodes = useMemo(() => {
   382→    let filtered = zipCodes as ZipCodeRecord[];
   383→
   384→    if (searchQuery.trim()) {
   385→      const q = searchQuery.trim().toLowerCase();
   386→      filtered = filtered.filter(
   387→        (z) =>
   388→          z.zipCode.toLowerCase().includes(q) ||
   389→          (z.zone && z.zone.toLowerCase().includes(q)) ||
   390→          (z.label && z.label.toLowerCase().includes(q)) ||
   391→          (z.message && z.message.toLowerCase().includes(q)),
   392→      );
   393→    }
   394→
   395→    if (statusFilter === "allowed") {
   396→      filtered = filtered.filter((z) => z.type === "allowed");
   397→    } else if (statusFilter === "blocked") {
   398→      filtered = filtered.filter((z) => z.type === "blocked");
   399→    }
   400→
   401→    return filtered;
   402→  }, [zipCodes, searchQuery, statusFilter]);
   403→
   404→  // Pagination
   405→  const totalPages = Math.max(1, Math.ceil(filteredZipCodes.length / PAGE_SIZE));
   406→  const paginatedZipCodes = useMemo(() => {
   407→    const start = (currentPage - 1) * PAGE_SIZE;
   408→    return filteredZipCodes.slice(start, start + PAGE_SIZE);
   409→  }, [filteredZipCodes, currentPage]);
   410→
   411→  // Reset to page 1 when search/filter changes
   412→  const handleSearchChange = useCallback((val: string) => {
   413→    setSearchQuery(val);
   414→    setCurrentPage(1);
   415→  }, []);
   416→
   417→  const handleFilterChange = useCallback((val: string) => {
   418→    setStatusFilter(val);
   419→    setCurrentPage(1);
   420→  }, []);
   421→
   422→  const handleCheck = useCallback(() => {
   423→    if (!checkZip.trim()) return;
   424→    const fd = new FormData();
   425→    fd.set("intent", "check");
   426→    fd.set("checkZip", checkZip);
   427→    fetcher.submit(fd, { method: "POST" });
   428→  }, [checkZip, fetcher]);
   429→
   430→  const handleAdd = useCallback(() => {
   431→    if (!newZip.trim()) return;
   432→    const fd = new FormData();
   433→    fd.set("intent", "add");
   434→    fd.set("zipCode", newZip);
   435→    fd.set("label", newLabel);
   436→    fd.set("zone", newZone);
   437→    fd.set("message", newMessage);
   438→    fd.set("eta", newEta);
   439→    fd.set("type", newType);
   440→    fetcher.submit(fd, { method: "POST" });
   441→    if (!actionError) {
   442→      setNewZip("");
   443→      setNewLabel("");
   444→      setNewZone("");
   445→      setNewMessage("");
   446→      setNewEta("");
   447→      setNewType("allowed");
   448→      setAddModalOpen(false);
   449→    }
   450→  }, [newZip, newLabel, newZone, newMessage, newEta, newType, fetcher, actionError]);
   451→
   452→  const handleDelete = useCallback(
   453→    (id: string) => {
   454→      const fd = new FormData();
   455→      fd.set("intent", "delete");
   456→      fd.set("id", id);
   457→      fetcher.submit(fd, { method: "POST" });
   458→      shopify.toast.show("Zip code removed");
   459→    },
   460→    [fetcher, shopify],
   461→  );
   462→
   463→  const handleOpenEdit = useCallback((z: ZipCodeRecord) => {
   464→    setEditId(z.id);
   465→    setEditZip(z.zipCode);
   466→    setEditLabel(z.label || "");
   467→    setEditZone(z.zone || "");
   468→    setEditMessage(z.message || "");
   469→    setEditEta(z.eta || "");
   470→    setEditType(z.type);
   471→    setEditIsActive(z.isActive);
   472→    setEditModalOpen(true);
   473→  }, []);
   474→
   475→  const handleUpdate = useCallback(() => {
   476→    if (!editZip.trim()) return;
   477→    const fd = new FormData();
   478→    fd.set("intent", "update");
   479→    fd.set("id", editId);
   480→    fd.set("zipCode", editZip);
   481→    fd.set("label", editLabel);
   482→    fd.set("zone", editZone);
   483→    fd.set("message", editMessage);
   484→    fd.set("eta", editEta);
   485→    fd.set("type", editType);
   486→    fd.set("isActive", String(editIsActive));
   487→    fetcher.submit(fd, { method: "POST" });
   488→    setEditModalOpen(false);
   489→    shopify.toast.show("Zip code updated");
   490→  }, [editId, editZip, editLabel, editZone, editMessage, editEta, editType, editIsActive, fetcher, shopify]);
   491→
   492→  const handleToggle = useCallback(
   493→    (id: string, isActive: boolean) => {
   494→      const fd = new FormData();
   495→      fd.set("intent", "toggle");
   496→      fd.set("id", id);
   497→      fd.set("isActive", String(isActive));
   498→      fetcher.submit(fd, { method: "POST" });
   499→    },
   500→    [fetcher],
   501→  );
   502→
   503→  const handleImport = useCallback(() => {
   504→    const dataToImport = csvText.trim();
   505→    if (!dataToImport) return;
   506→    const fd = new FormData();
   507→    fd.set("intent", "bulk-import");
   508→    fd.set("csvData", dataToImport);
   509→    fetcher.submit(fd, { method: "POST" });
   510→  }, [csvText, fetcher]);
   511→
   512→  const handleFileUpload = useCallback(
   513→    (_files: File[], acceptedFiles: File[]) => {
   514→      if (acceptedFiles.length > 0) {
   515→        const file = acceptedFiles[0];
   516→        setImportFile(file);
   517→        const reader = new FileReader();
   518→        reader.onload = (e) => {
   519→          const text = e.target?.result;
   520→          if (typeof text === "string") {
   521→            setCsvText(text);
   522→          }
   523→        };
   524→        reader.readAsText(file);
   525→      }
   526→    },
   527→    [],
   528→  );
   529→
   530→  const handleExport = useCallback(() => {
   531→    const fd = new FormData();
   532→    fd.set("intent", "export");
   533→    fetcher.submit(fd, { method: "POST" });
   534→  }, [fetcher]);
   535→
   536→  // Trigger download when export data arrives
   537→  const exportCsv =
   538→    fetcher.data &&
   539→    "action" in fetcher.data &&
   540→    fetcher.data.action === "export" &&
   541→    "csv" in fetcher.data
   542→      ? (fetcher.data.csv as string)
   543→      : null;
   544→
   545→  if (exportCsv) {
   546→    const blob = new Blob([exportCsv], { type: "text/csv" });
   547→    const url = URL.createObjectURL(blob);
   548→    const a = document.createElement("a");
   549→    a.href = url;
   550→    a.download = "zip-codes.csv";
   551→    a.click();
   552→    URL.revokeObjectURL(url);
   553→  }
   554→
   555→  const typeOptions = [
   556→    { label: "Allowed — permit this zip code", value: "allowed" },
   557→    ...(limits.allowBlocked
   558→      ? [{ label: "Blocked — deny this zip code", value: "blocked" }]
   559→      : []),
   560→  ];
   561→
   562→  const filterOptions = [
   563→    { label: "All", value: "all" },
   564→    { label: "Allowed", value: "allowed" },
   565→    { label: "Blocked", value: "blocked" },
   566→  ];
   567→
   568→  const tableRows = paginatedZipCodes.map((z) => [
   569→    <Text as="span" fontWeight="bold" key={`zip-${z.id}`}>
   570→      {z.zipCode}
   571→    </Text>,
   572→    z.zone || (
   573→      <Text as="span" tone="subdued">
   574→        —
   575→      </Text>
   576→    ),
   577→    <InlineStack gap="300" blockAlign="center" key={`status-${z.id}`}>
   578→      <Tooltip content={z.isActive ? "Click to deactivate" : "Click to activate"}>
   579→        <Button
   580→          variant="plain"
   581→          tone={z.isActive ? "success" : undefined}
   582→          onClick={() => handleToggle(z.id, z.isActive)}
   583→          accessibilityLabel={z.isActive ? "Deactivate zip code" : "Activate zip code"}
   584→        >
   585→          {z.isActive ? "Active" : "Inactive"}
   586→        </Button>
   587→      </Tooltip>
   588→      <Badge tone={z.type === "allowed" ? "success" : "critical"}>
   589→        {z.type === "allowed" ? "Allow" : "Block"}
   590→      </Badge>
   591→    </InlineStack>,
   592→    z.message || (
   593→      <Text as="span" tone="subdued">
   594→        —
   595→      </Text>
   596→    ),
   597→    z.eta || (
   598→      <Text as="span" tone="subdued">
   599→        —
   600→      </Text>
   601→    ),
   602→    <InlineStack gap="200" blockAlign="center" key={`actions-${z.id}`}>
